# Basketly promo codes: pricing module, tests and worked example

The cart below fails the FRESH10 minimum. It is $47.45 in total, but only $35.46 of that is non-alcohol, so it does not reach $40.00. Section 3 shows the full result.

I couldn't run anything from here. The expected values in the tests were computed by hand using exact integer arithmetic, so please run `vitest` before merging.

---

## 1. `pricing.ts`

**Breaking change:** `LineItem.unitPrice` (a dollar float) is now `unitPriceCents` (an integer). Callers that still hold dollar prices can convert at the boundary with `dollarsToCents`.

```ts
// pricing.ts
// All money is integer cents. All rates are integer basis points (1 bp = 0.01%).

export type Category = 'grocery' | 'household' | 'alcohol';
export type DiscountableCategory = Exclude<Category, 'alcohol'>;
export type MemberTier = 'none' | 'plus';
/** Calendar date in the store's local time zone: 'YYYY-MM-DD'. */
export type IsoDate = string;

export interface LineItem {
  sku: string;
  name: string;
  /** Integer cents, e.g. 199 for $1.99. */
  unitPriceCents: number;
  /** Positive integer. */
  qty: number;
  category: Category;
}

export interface Cart {
  items: readonly LineItem[];
  memberTier: MemberTier;
}

// ---------- Configuration as data ----------

interface PromoBase {
  code: string;
  minEligibleSubtotalCents: number;
  /** Inclusive, store-local date. */
  validThrough: IsoDate;
  /** Typed so alcohol cannot be listed (legal); also enforced at runtime. */
  eligibleCategories: readonly DiscountableCategory[];
}
export type PromoDefinition =
  | (PromoBase & { type: 'percent'; basisPoints: number })
  | (PromoBase & { type: 'fixed'; amountCents: number });

export const PROMO_TABLE: readonly PromoDefinition[] = [
  { code: 'FRESH10', type: 'percent', basisPoints: 1000, minEligibleSubtotalCents: 4000, validThrough: '2025-12-31', eligibleCategories: ['grocery', 'household'] },
  { code: 'SAVE5',   type: 'fixed',   amountCents: 500,  minEligibleSubtotalCents: 2500, validThrough: '2025-06-30', eligibleCategories: ['grocery', 'household'] },
  { code: 'HOME15',  type: 'percent', basisPoints: 1500, minEligibleSubtotalCents: 0,    validThrough: '2025-12-31', eligibleCategories: ['household'] },
];

const PROMOS_BY_CODE: ReadonlyMap<string, PromoDefinition> = new Map(
  PROMO_TABLE.map((p) => [p.code.toUpperCase(), p]),
);

export const MEMBER_DISCOUNT_BPS: Readonly<Record<MemberTier, number>> = { none: 0, plus: 500 };
export const TAX_BPS: Readonly<Record<Category, number>> = { grocery: 0, household: 825, alcohol: 825 };
/** ASSUMPTION: confirm the store time zone (8.25% suggests Texas). */
export const STORE_TIME_ZONE = 'America/Chicago';
const BPS_DENOMINATOR = 10_000;

// ---------- Output types ----------

export type PromoRejectionReason = 'unknown' | 'expired' | 'below_minimum' | 'no_eligible_items';
export type PromoOutcome =
  | { status: 'none' }
  | { status: 'applied'; code: string; discountCents: number }
  | { status: 'rejected'; code: string; reason: PromoRejectionReason };

export interface PricedLine {
  sku: string;
  name: string;
  category: Category;
  qty: number;
  unitPriceCents: number;
  grossCents: number;
  memberDiscountCents: number;
  promoDiscountCents: number;
  netCents: number;
  taxCents: number;
  totalCents: number;
}

export interface PricedTotals {
  subtotalCents: number;
  memberDiscountCents: number;
  promoDiscountCents: number;
  taxCents: number;
  totalCents: number;
}

export interface PricedCart {
  lines: PricedLine[];
  totals: PricedTotals;
  promo: PromoOutcome;
}

// ---------- Pure helpers ----------

const sum = (xs: readonly number[]): number => xs.reduce((s, x) => s + x, 0);

export function isDiscountable(c: Category): c is DiscountableCategory {
  return c !== 'alcohol';
}

/** Exact round-half-up of numerator/denominator for non-negative safe integers. */
export function roundHalfUpDiv(numerator: number, denominator: number): number {
  if (!Number.isSafeInteger(numerator) || numerator < 0 || !Number.isSafeInteger(denominator) || denominator <= 0) {
    throw new RangeError(`roundHalfUpDiv: invalid operands ${numerator}/${denominator}`);
  }
  const r = numerator % denominator;
  const q = (numerator - r) / denominator;
  return 2 * r >= denominator ? q + 1 : q;
}

export function applyBasisPoints(amountCents: number, bps: number): number {
  return roundHalfUpDiv(amountCents * bps, BPS_DENOMINATOR);
}

/**
 * Splits a fixed amount across lines in proportion to `weights`.
 * - The total is capped at sum(weights).
 * - Each share is rounded half-up.
 * - The remainder (positive or negative) goes to the largest line; ties go to the earliest line.
 * - If needed, the remainder spills to the next largest line so that 0 <= share <= weight.
 */
export function allocateFixed(amountCents: number, weights: readonly number[]): number[] {
  const total = sum(weights);
  const target = Math.min(amountCents, total);
  if (target <= 0) return weights.map(() => 0);

  const shares = weights.map((w) => roundHalfUpDiv(target * w, total)); // each <= w because target <= total
  let remainder = target - sum(shares);
  const order = weights.map((_, i) => i).sort((a, b) => weights[b] - weights[a] || a - b);
  for (const i of order) {
    if (remainder === 0) break;
    const delta = remainder > 0
      ? Math.min(remainder, weights[i] - shares[i])
      : -Math.min(-remainder, shares[i]);
    shares[i] += delta;
    remainder -= delta;
  }
  return shares;
}

export function normalizePromoCode(raw?: string | null): string | null {
  const code = (raw ?? '').trim().toUpperCase();
  return code === '' ? null : code;
}

export function storeLocalDate(now: Date, timeZone: string = STORE_TIME_ZONE): IsoDate {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(now);
  const get = (t: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === t)!.value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

/** Boundary helper for callers still holding dollar floats (1.99 -> 199). */
export function dollarsToCents(dollars: number): number {
  const cents = Math.round(dollars * 100);
  if (!Number.isFinite(dollars) || Math.abs(dollars * 100 - cents) > 1e-6) {
    throw new RangeError(`Not a whole-cent amount: ${dollars}`);
  }
  return cents;
}

function assertIsoDate(d: string): void {
  if (!/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(d)) {
    throw new RangeError(`today must be 'YYYY-MM-DD', got '${d}'`);
  }
}

function validateCart(cart: Cart): void {
  if (!Object.hasOwn(MEMBER_DISCOUNT_BPS, cart.memberTier)) {
    throw new RangeError(`Unknown member tier: ${cart.memberTier}`);
  }
  for (const it of cart.items) {
    if (!Number.isSafeInteger(it.unitPriceCents) || it.unitPriceCents < 0) {
      throw new RangeError(`${it.sku}: unitPriceCents must be a non-negative integer`);
    }
    if (!Number.isSafeInteger(it.qty) || it.qty < 1) {
      throw new RangeError(`${it.sku}: qty must be a positive integer`);
    }
    if (!Object.hasOwn(TAX_BPS, it.category)) {
      throw new RangeError(`${it.sku}: unknown category ${it.category}`);
    }
    if (!Number.isSafeInteger(it.unitPriceCents * it.qty)) {
      throw new RangeError(`${it.sku}: line amount overflows`);
    }
  }
}

// ---------- Promo resolution ----------

export interface DiscountBase {
  category: Category;
  grossCents: number;
  afterMemberCents: number;
}

function isPromoEligible(def: PromoDefinition, category: Category): boolean {
  return isDiscountable(category) && def.eligibleCategories.includes(category);
}

/** Never throws for any code string. Rejection precedence: unknown > expired > no_eligible_items > below_minimum. */
export function resolvePromo(
  rawCode: string | null | undefined,
  lines: readonly DiscountBase[],
  today: IsoDate,
): { promo: PromoOutcome; discounts: number[] } {
  const none = lines.map(() => 0);
  const code = normalizePromoCode(rawCode);
  if (code === null) return { promo: { status: 'none' }, discounts: none };

  const reject = (reason: PromoRejectionReason) => ({
    promo: { status: 'rejected', code, reason } as const,
    discounts: none,
  });

  const def = PROMOS_BY_CODE.get(code);
  if (!def) return reject('unknown');
  if (today > def.validThrough) return reject('expired'); // ISO dates compare lexicographically

  const eligible = lines.map((l) => isPromoEligible(def, l.category));
  if (!eligible.some(Boolean)) return reject('no_eligible_items');

  const eligibleGross = sum(lines.map((l, i) => (eligible[i] ? l.grossCents : 0)));
  if (eligibleGross < def.minEligibleSubtotalCents) return reject('below_minimum');

  const weights = lines.map((l, i) => (eligible[i] ? l.afterMemberCents : 0));
  const discounts = def.type === 'percent'
    ? weights.map((w) => applyBasisPoints(w, def.basisPoints))
    : allocateFixed(def.amountCents, weights);

  return { promo: { status: 'applied', code, discountCents: sum(discounts) }, discounts };
}

// ---------- Entry point ----------

export function priceCart(
  cart: Cart,
  promoCode?: string | null,
  today: IsoDate = storeLocalDate(new Date()), // pass explicitly for deterministic pricing
): PricedCart {
  validateCart(cart);
  assertIsoDate(today);

  const memberBps = MEMBER_DISCOUNT_BPS[cart.memberTier];
  const base = cart.items.map((item) => {
    const grossCents = item.unitPriceCents * item.qty;
    const memberDiscountCents = isDiscountable(item.category) ? applyBasisPoints(grossCents, memberBps) : 0;
    return { item, category: item.category, grossCents, memberDiscountCents, afterMemberCents: grossCents - memberDiscountCents };
  });

  const { promo, discounts } = resolvePromo(promoCode, base, today);

  const lines = base.map((b, i): PricedLine => {
    const promoDiscountCents = discounts[i];
    const netCents = b.afterMemberCents - promoDiscountCents;
    const taxCents = applyBasisPoints(netCents, TAX_BPS[b.category]);
    return {
      sku: b.item.sku, name: b.item.name, category: b.category, qty: b.item.qty,
      unitPriceCents: b.item.unitPriceCents, grossCents: b.grossCents,
      memberDiscountCents: b.memberDiscountCents, promoDiscountCents, netCents,
      taxCents, totalCents: netCents + taxCents,
    };
  });

  const total = (k: keyof PricedTotals & keyof PricedLine | 'grossCents') =>
    sum(lines.map((l) => l[k as keyof PricedLine] as number));

  return {
    lines,
    totals: {
      subtotalCents: total('grossCents'),
      memberDiscountCents: total('memberDiscountCents'),
      promoDiscountCents: total('promoDiscountCents'),
      taxCents: total('taxCents'),
      totalCents: total('totalCents'),
    },
    promo,
  };
}
```

