## 2. `pricing.test.ts`

```ts
import { describe, it, expect } from 'vitest';
import {
  priceCart, allocateFixed, roundHalfUpDiv, applyBasisPoints, normalizePromoCode,
  storeLocalDate, dollarsToCents, PROMO_TABLE,
  type Cart, type Category, type LineItem, type MemberTier, type PricedCart, type PricedLine,
} from './pricing';

const JULY = '2025-07-02';      // FRESH10/HOME15 valid, SAVE5 expired
const JUNE = '2025-06-01';      // all codes valid

let seq = 0;
function item(category: Category, unitPriceCents: number, qty = 1): LineItem {
  seq += 1;
  return { sku: `SKU-${seq}`, name: `${category} ${seq}`, unitPriceCents, qty, category };
}
const cart = (memberTier: MemberTier, ...items: LineItem[]): Cart => ({ memberTier, items });
const col = <K extends keyof PricedLine>(r: PricedCart, k: K) => r.lines.map((l) => l[k]);

function expectConsistent(r: PricedCart) {
  for (const l of r.lines) {
    expect(l.grossCents).toBe(l.unitPriceCents * l.qty);
    expect(l.netCents).toBe(l.grossCents - l.memberDiscountCents - l.promoDiscountCents);
    expect(l.netCents).toBeGreaterThanOrEqual(0);
    expect(l.totalCents).toBe(l.netCents + l.taxCents);
    for (const v of [l.memberDiscountCents, l.promoDiscountCents, l.taxCents]) expect(Number.isInteger(v)).toBe(true);
    if (l.category === 'alcohol') expect(l.memberDiscountCents + l.promoDiscountCents).toBe(0);
  }
  const s = (k: keyof PricedLine) => r.lines.reduce((a, l) => a + (l[k] as number), 0);
  expect(r.totals).toEqual({
    subtotalCents: s('grossCents'), memberDiscountCents: s('memberDiscountCents'),
    promoDiscountCents: s('promoDiscountCents'), taxCents: s('taxCents'), totalCents: s('totalCents'),
  });
  if (r.promo.status === 'applied') expect(r.promo.discountCents).toBe(r.totals.promoDiscountCents);
  else expect(r.totals.promoDiscountCents).toBe(0);
}

describe('worked example (Plus, fresh10, 2025-07-02)', () => {
  it('rejects FRESH10 because only $35.46 is non-alcohol', () => {
    const r = priceCart({
      memberTier: 'plus',
      items: [
        { sku: 'APL', name: 'Organic apples', unitPriceCents: 199, qty: 3, category: 'grocery' },
        { sku: 'SRD', name: 'Sourdough loaf', unitPriceCents: 649, qty: 1, category: 'grocery' },
        { sku: 'SOAP', name: 'Dish soap', unitPriceCents: 425, qty: 2, category: 'household' },
        { sku: 'IPA', name: 'IPA 6-pack', unitPriceCents: 1199, qty: 1, category: 'alcohol' },
        { sku: 'OIL', name: 'Olive oil', unitPriceCents: 1450, qty: 1, category: 'grocery' },
      ],
    }, 'fresh10', JULY);
    expect(r.promo).toEqual({ status: 'rejected', code: 'FRESH10', reason: 'below_minimum' });
    expect(col(r, 'memberDiscountCents')).toEqual([30, 32, 43, 0, 73]);
    expect(col(r, 'taxCents')).toEqual([0, 0, 67, 99, 0]);
    expect(r.totals).toEqual({ subtotalCents: 4745, memberDiscountCents: 178, promoDiscountCents: 0, taxCents: 166, totalCents: 4733 });
    expectConsistent(r);
  });
});

describe('code lookup', () => {
  it.each(['FRESH10', 'fresh10', '  FrEsH10 '])('is case-insensitive and trims: %j', (code) => {
    const r = priceCart(cart('none', item('grocery', 4000)), code, JULY);
    expect(r.promo).toEqual({ status: 'applied', code: 'FRESH10', discountCents: 400 });
    expectConsistent(r);
  });

  it('treats missing or blank codes as no promo', () => {
    for (const c of [undefined, null, '', '   ']) {
      expect(priceCart(cart('none', item('grocery', 4000)), c, JULY).promo).toEqual({ status: 'none' });
    }
    expect(normalizePromoCode('  x ')).toBe('X');
  });

  it('rejects unknown codes and returns the no-promo price', () => {
    const c = cart('plus', item('grocery', 5000), item('household', 1000));
    const r = priceCart(c, 'FRESH20', JULY);
    expect(r.promo).toEqual({ status: 'rejected', code: 'FRESH20', reason: 'unknown' });
    expect(r.totals).toEqual(priceCart(c, undefined, JULY).totals);
    expectConsistent(r);
  });

  it.each(['__proto__', 'constructor', 'x'.repeat(1000), '🍺', 'SAVE5; DROP'])('never throws for odd input %j', (code) => {
    expect(() => priceCart(cart('none', item('grocery', 4000)), code, JULY)).not.toThrow();
  });
});

describe('validity dates (inclusive, store-local)', () => {
  const c = cart('none', item('grocery', 4000));
  it('SAVE5 is valid on 2025-06-30 and expired on 2025-07-01', () => {
    expect(priceCart(c, 'SAVE5', '2025-06-30').promo.status).toBe('applied');
    expect(priceCart(c, 'SAVE5', '2025-07-01').promo).toEqual({ status: 'rejected', code: 'SAVE5', reason: 'expired' });
  });
  it('FRESH10 is valid on 2025-12-31 and expired on 2026-01-01', () => {
    expect(priceCart(c, 'FRESH10', '2025-12-31').promo.status).toBe('applied');
    expect(priceCart(c, 'FRESH10', '2026-01-01').promo).toMatchObject({ reason: 'expired' });
  });
  it('reports expired ahead of eligibility problems', () => {
    expect(priceCart(cart('none', item('alcohol', 100)), 'SAVE5', '2025-07-01').promo).toMatchObject({ reason: 'expired' });
  });
  it('derives the store-local date, not the UTC date', () => {
    expect(storeLocalDate(new Date('2025-07-01T03:00:00Z'))).toBe('2025-06-30');
    expect(storeLocalDate(new Date('2025-07-01T05:00:00Z'))).toBe('2025-07-01');
  });
  it('rejects malformed dates', () => {
    expect(() => priceCart(c, 'FRESH10', '07/02/2025')).toThrow(RangeError);
  });
});

describe('minimum eligible subtotal', () => {
  it('does not count alcohol', () => {
    const r = priceCart(cart('none', item('grocery', 3999), item('alcohol', 2000)), 'FRESH10', JULY);
    expect(r.promo).toMatchObject({ reason: 'below_minimum' });
  });
  it('is inclusive at exactly the minimum', () => {
    expect(priceCart(cart('none', item('grocery', 2499)), 'SAVE5', JUNE).promo).toMatchObject({ reason: 'below_minimum' });
    expect(priceCart(cart('none', item('grocery', 2500)), 'SAVE5', JUNE).promo).toMatchObject({ status: 'applied', discountCents: 500 });
  });
  it('is measured before the member discount', () => {
    const r = priceCart(cart('plus', item('grocery', 4000)), 'FRESH10', JULY);
    expect(r.promo.status).toBe('applied');
    expect(col(r, 'memberDiscountCents')).toEqual([200]);
    expect(col(r, 'promoDiscountCents')).toEqual([380]);
  });
});

describe('no eligible items', () => {
  it('HOME15 without household items', () => {
    expect(priceCart(cart('none', item('grocery', 9000)), 'HOME15', JULY).promo).toMatchObject({ reason: 'no_eligible_items' });
  });
  it('alcohol-only cart reports no_eligible_items, not below_minimum', () => {
    expect(priceCart(cart('none', item('alcohol', 9000)), 'FRESH10', JULY).promo).toMatchObject({ reason: 'no_eligible_items' });
  });
  it('empty cart', () => {
    const r = priceCart(cart('plus'), 'FRESH10', JULY);
    expect(r.promo).toMatchObject({ reason: 'no_eligible_items' });
    expect(r.totals.totalCents).toBe(0);
  });
});

describe('alcohol and ordering', () => {
  it('applies the member discount first, the promo on the remainder, and never discounts alcohol', () => {
    const r = priceCart(cart('plus', item('grocery', 5000), item('alcohol', 2000)), 'FRESH10', JULY);
    expect(col(r, 'memberDiscountCents')).toEqual([250, 0]);
    expect(col(r, 'promoDiscountCents')).toEqual([475, 0]);
    expect(col(r, 'taxCents')).toEqual([0, 165]);
    expect(r.totals.totalCents).toBe(6440);
    expectConsistent(r);
  });
  it('no code in the table targets alcohol', () => {
    for (const p of PROMO_TABLE) expect(p.eligibleCategories as readonly string[]).not.toContain('alcohol');
  });
  it('HOME15 discounts household lines only, and tax uses the post-discount amount', () => {
    const r = priceCart(cart('none', item('grocery', 2000), item('household', 1000)), 'HOME15', JULY);
    expect(col(r, 'promoDiscountCents')).toEqual([0, 150]);
    expect(col(r, 'taxCents')).toEqual([0, 70]); // 850 * 8.25% = 70.125
    expect(r.totals.totalCents).toBe(2920);
  });
});

describe('tax', () => {
  it('exempts grocery and taxes household and alcohol at 8.25%, half-up', () => {
    const r = priceCart(cart('none', item('grocery', 1000), item('household', 1000), item('alcohol', 1000)), undefined, JULY);
    expect(col(r, 'taxCents')).toEqual([0, 83, 83]); // 82.5 -> 83
  });
  it('rounds per line, not on the aggregate', () => {
    const r = priceCart(cart('none', item('household', 200), item('household', 200)), undefined, JULY);
    expect(r.totals.taxCents).toBe(34); // 16.5 -> 17, twice (aggregate would be 33)
  });
});

describe('rounding', () => {
  it('rounds member and percent discounts half-up', () => {
    expect(col(priceCart(cart('plus', item('household', 850)), undefined, JULY), 'memberDiscountCents')).toEqual([43]);
    expect(col(priceCart(cart('none', item('grocery', 4005)), 'FRESH10', JULY), 'promoDiscountCents')).toEqual([401]);
  });
  it('roundHalfUpDiv and applyBasisPoints are exact', () => {
    expect([roundHalfUpDiv(1, 2), roundHalfUpDiv(3, 2), roundHalfUpDiv(1, 3), roundHalfUpDiv(2, 3)]).toEqual([1, 2, 0, 1]);
    expect(applyBasisPoints(1000, 825)).toBe(83);
    expect(() => roundHalfUpDiv(-1, 2)).toThrow(RangeError);
  });
});

describe('fixed discount allocation', () => {
  it('sends a negative remainder to the largest line (tie goes to the first)', () => {
    const r = priceCart(cart('none', item('grocery', 1000), item('grocery', 1000), item('grocery', 1000)), 'SAVE5', JUNE);
    expect(col(r, 'promoDiscountCents')).toEqual([166, 167, 167]);
    expectConsistent(r);
  });
  it('sends a positive remainder to the largest line', () => {
    const six = Array.from({ length: 6 }, () => item('grocery', 1000));
    expect(col(priceCart(cart('none', ...six), 'SAVE5', JUNE), 'promoDiscountCents')).toEqual([85, 83, 83, 83, 83, 83]);
  });
  it('allocates proportionally and taxes each line after allocation', () => {
    const r = priceCart(cart('none', item('household', 2000), item('household', 700), item('household', 300)), 'SAVE5', JUNE);
    expect(col(r, 'promoDiscountCents')).toEqual([333, 117, 50]);
    expect(col(r, 'taxCents')).toEqual([138, 48, 21]);
    expect(r.totals.totalCents).toBe(2707);
  });
  it('weights by post-member amounts', () => {
    const r = priceCart(cart('plus', item('grocery', 2000), item('grocery', 1000)), 'SAVE5', JUNE);
    expect(col(r, 'memberDiscountCents')).toEqual([100, 50]);
    expect(col(r, 'promoDiscountCents')).toEqual([333, 167]);
  });
  it('excludes alcohol from allocation', () => {
    const r = priceCart(cart('none', item('grocery', 3000), item('alcohol', 5000)), 'SAVE5', JUNE);
    expect(col(r, 'promoDiscountCents')).toEqual([500, 0]);
    expect(r.totals.totalCents).toBe(7913);
  });
  it('allocateFixed edge cases', () => {
    expect(allocateFixed(500, [100, 200])).toEqual([100, 200]);        // capped at eligible amount
    expect(allocateFixed(500, [0, 0])).toEqual([0, 0]);
    expect(allocateFixed(10, [1000, 3000, 3000])).toEqual([1, 5, 4]);  // largest wins, tie goes to the first
    expect(allocateFixed(1, [1, 1, 1])).toEqual([1, 0, 0]);
    expect(allocateFixed(2, [1, 1, 1])).toEqual([0, 1, 1]);
  });
});

describe('input validation', () => {
  it.each([item('grocery', 199, 0), item('grocery', 199, 1.5), item('grocery', 1.99), item('grocery', -1)])(
    'throws on invalid line %#', (bad) => {
      expect(() => priceCart(cart('none', bad), undefined, JULY)).toThrow(RangeError);
    });
  it('dollarsToCents', () => {
    expect([dollarsToCents(1.99), dollarsToCents(14.5), dollarsToCents(4.35)]).toEqual([199, 1450, 435]);
    expect(() => dollarsToCents(1.999)).toThrow(RangeError);
  });
});
```

